{
  "name": "UHFQA量子分析控制器",
  "name_en": "UHFQA Quantum Analyzer/Controller",
  "manufacturer": "Zurich Instruments",
  "description": "这是一台苏黎世仪器的 UHFQA 超高频量子分析/控制仪器，用于量子实验中的读出脉冲生成、AWG波形下载、积分权重配置、DIO触发与时序校准，以及光谱测量模式配置。",
  "description_en": "This is a Zurich Instruments UHFQA ultra-high-frequency quantum analyzer/controller used in quantum experiments for readout pulse generation, AWG waveform loading, integration weight configuration, DIO triggering and timing calibration, and spectroscopy mode setup.",
  "actions": [
    {
      "action_name": "auto-load_default_settings",
      "description": "加载仪器默认设置，并可上传默认AWG序列与读出相关配置。",
      "description_en": "Load default instrument settings, optionally uploading a default AWG sequence and readout-related configuration."
    },
    {
      "action_name": "auto-load_awg_program_from_file",
      "description": "从文本文件加载AWG程序到仪器。",
      "description_en": "Load an AWG program onto the instrument from a text file."
    },
    {
      "action_name": "auto-awg_file",
      "description": "通过兼容接口从文件加载AWG程序。",
      "description_en": "Load an AWG program from a file through a backward-compatible interface."
    },
    {
      "action_name": "auto-awg_update_waveform",
      "description": "更新指定索引的AWG波形数据。",
      "description_en": "Update AWG waveform data at a specified index."
    },
    {
      "action_name": "auto-plot_dio",
      "description": "绘制DIO位线数据以检查数字输入输出时序。",
      "description_en": "Plot DIO bit-line data to inspect digital input/output timing."
    },
    {
      "action_name": "auto-prepare_SSB_weight_and_rotation",
      "description": "配置单边带读出的积分权重与旋转参数。",
      "description_en": "Prepare integration weights and rotation parameters for single-sideband readout."
    },
    {
      "action_name": "auto-prepare_DSB_weight_and_rotation",
      "description": "配置双边带读出的积分权重与旋转参数。",
      "description_en": "Prepare integration weights and rotation parameters for double-sideband readout."
    },
    {
      "action_name": "auto-plot_dio_snapshot",
      "description": "绘制当前DIO快照以查看数字位状态。",
      "description_en": "Plot a current DIO snapshot to inspect digital bit states."
    },
    {
      "action_name": "auto-snapshot_base",
      "description": "获取仪器当前状态的JSON兼容快照。",
      "description_en": "Get a JSON-compatible snapshot of the current instrument state."
    },
    {
      "action_name": "auto-awg_sequence_acquisition_and_DIO_triggered_pulse",
      "description": "加载并配置由DIO触发的脉冲与采集AWG序列。",
      "description_en": "Load and configure an AWG sequence for acquisition with DIO-triggered pulses."
    },
    {
      "action_name": "auto-awg_sequence_acquisition_and_DIO_RED_test",
      "description": "加载用于DIO相关RED测试的脉冲与采集AWG序列。",
      "description_en": "Load an AWG sequence for acquisition and pulse generation in a DIO-related RED test."
    },
    {
      "action_name": "auto-awg_sequence_test_pattern",
      "description": "加载用于数字测试图样输出的AWG序列。",
      "description_en": "Load an AWG sequence that outputs a digital test pattern."
    },
    {
      "action_name": "auto-awg_sequence_acquisition_and_pulse",
      "description": "加载同时执行脉冲输出与数据采集的AWG序列。",
      "description_en": "Load an AWG sequence that performs pulse output together with data acquisition."
    },
    {
      "action_name": "auto-awg_sequence_acquisition",
      "description": "加载仅用于数据采集的AWG序列。",
      "description_en": "Load an AWG sequence for data acquisition only."
    },
    {
      "action_name": "auto-awg_debug_acquisition",
      "description": "加载带调试延迟设置的数据采集序列。",
      "description_en": "Load a data acquisition sequence with debug delay settings."
    },
    {
      "action_name": "auto-awg_sequence_acquisition_and_pulse_SSB",
      "description": "加载单边带调制读出脉冲与采集AWG序列。",
      "description_en": "Load an AWG sequence for single-sideband modulated readout pulse generation and acquisition."
    },
    {
      "action_name": "auto-spec_mode_on",
      "description": "开启光谱测量模式并配置内部振荡器、窗口和读出参数。",
      "description_en": "Enable spectroscopy mode and configure the internal oscillator, windowing, and readout parameters."
    },
    {
      "action_name": "auto-spec_mode_off",
      "description": "关闭光谱测量模式并恢复默认读出配置。",
      "description_en": "Disable spectroscopy mode and restore default readout configuration."
    },
    {
      "action_name": "auto-output_dio_calibration_data",
      "description": "输出DIO校准数据用于数字接口时序校准。",
      "description_en": "Output DIO calibration data for digital interface timing calibration."
    },
    {
      "action_name": "auto-calibrate_dio_protocol",
      "description": "校准DIO协议时序与延迟设置。",
      "description_en": "Calibrate DIO protocol timing and delay settings."
    },
    {
      "action_name": "auto-calibrate_CC_dio_protocol",
      "description": "与中央控制器配合校准DIO协议。",
      "description_en": "Calibrate the DIO protocol in coordination with a central controller."
    }
  ],
  "tag_hints": [
    "quantum readout",
    "UHFQA",
    "AWG waveform generation",
    "integration weights",
    "DIO timing calibration",
    "single-sideband readout",
    "spectroscopy mode",
    "Zurich Instruments"
  ]
}

